import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"AVS Landing Zone — enumerated source for the Azure VMware Solution Landing Zone Assessment Review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/avs-landing-zone-question-set.md","filePath":"frameworks/avs-landing-zone-question-set.md"}'),r={name:"frameworks/avs-landing-zone-question-set.md"};function i(d,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="avs-landing-zone-—-enumerated-source-for-the-azure-vmware-solution-landing-zone-assessment-review" tabindex="-1">AVS Landing Zone — enumerated source for the Azure VMware Solution Landing Zone Assessment Review <a class="header-anchor" href="#avs-landing-zone-—-enumerated-source-for-the-azure-vmware-solution-landing-zone-assessment-review" aria-label="Permalink to &quot;AVS Landing Zone — enumerated source for the Azure VMware Solution Landing Zone Assessment Review&quot;">​</a></h1><p><strong>Enumerated 2026-08-01. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p><strong>Framework version:</strong> Not versioned by Microsoft — both the interactive assessment and the CAF scenario documentation it is built from carry no release number. The extraction date above (2026-08-01) is the version, per <code>docs/frameworks/README.md</code>; re-date this line when this file is next re-verified.</p><p>This is the AB#6810 enumeration for target #7 in the audit&#39;s fourteen-assessment programme (<code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §14): <em>&quot;Azure VMware Solution Landing Zone Assessment Review — pairs with #6 [WAF AVS workload] — platform readiness rather than workload.&quot;</em> No rule file exists against this framework yet; that is deliberate — per DQ12, a rule file is not written until its source is enumerated here first.</p><h2 id="what-this-is" tabindex="-1">What this is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What this is&quot;">​</a></h2><p>Microsoft publishes <strong>two</strong> artefacts under this name, and they are not the same thing:</p><ol><li><strong>&quot;Azure VMware Solution Landing Zone Assessment Review&quot;</strong> — an interactive assessment on the Microsoft Assessments platform (<a href="https://learn.microsoft.com/en-us/assessments/43a1998e-2cb9-403c-b257-dffa8ceafd63" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/assessments/43a1998e-2cb9-403c-b257-dffa8ceafd63</a>), ~30 minutes, multiple-choice/multiple-response, &quot;40+ actionable recommendations.&quot; Its questions are not published — same limitation as SMART (see <code>smart-question-set.md</code>).</li><li><strong>&quot;Azure landing zone review for Microsoft Azure VMware Solution&quot;</strong> (<a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/scenarios/azure-vmware/ready" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/scenarios/azure-vmware/ready</a>) — a documentation page under the CAF Ready methodology&#39;s AVS scenario. This one <strong>is</strong> fully published: a checklist of best-practice statements grouped under 8 named areas.</li></ol><p>This enumeration is built from document (2), because it is the only one of the two with retrievable content. The interactive assessment (1) almost certainly draws on the same 8 areas — the landing page names them explicitly (&quot;resource organization, Entra ID usage, network topology, management and monitoring, business continuity, HCX and governance&quot;) — but its actual question text and per-question scoring are not extractable, so no coverage percentage against assessment (1) can be claimed from this enumeration.</p><h2 id="verification-method-—-and-the-one-thing-this-enumeration-is-not" tabindex="-1">Verification method — and the one thing this enumeration is NOT <a class="header-anchor" href="#verification-method-—-and-the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;Verification method — and the one thing this enumeration is NOT&quot;">​</a></h2><p><strong>What was read (2026-08-01):</strong></p><table tabindex="0"><thead><tr><th>Source</th><th>What it gave</th></tr></thead><tbody><tr><td>The AVS Landing Zone Assessment Review landing page (assessment ID <code>43a1998e-…</code>)</td><td>Confirms the assessment exists, its title, duration, and format. <strong>No question text.</strong></td></tr><tr><td><em>Azure landing zone review for Microsoft Azure VMware Solution</em> (<code>scenarios/azure-vmware/ready</code>)</td><td>The full, fetched content of the 8-area checklist below</td></tr><tr><td><em>Azure VMware Solution landing zone accelerator</em> (<code>scenarios/azure-vmware/enterprise-scale-landing-zone</code>)</td><td>Confirms the 8 areas map 1:1 to the accelerator&#39;s design-guideline articles (identity, network, management/monitoring, BC/DR, security/governance/compliance, platform automation)</td></tr></tbody></table><p><strong>⚠️ Microsoft&#39;s own interactive-assessment question TEXT and NUMBERS are not published.</strong> This enumeration is the CAF documentation page&#39;s checklist content, not the assessment&#39;s question bank. The <code>AVS-*</code> identifiers are <strong>Scout&#39;s own</strong>, stable and citable, not Microsoft&#39;s.</p><p><strong>Granularity rule applied throughout:</strong> each item below is a bullet point or a single declarative sentence taken directly from the source page — nothing has been split further or invented. Where the source states one undifferentiated sentence covering several concerns (e.g. area A), it remains one item here rather than being decomposed into sub-claims the source didn&#39;t make separately.</p><p><strong>Shelf life.</strong> This is a scenario page inside the actively-rewritten CAF tree (see the audit&#39;s §8 currency warnings). Re-verify before quoting, and re-date this page when you do.</p><h2 id="the-enumeration" tabindex="-1">The enumeration <a class="header-anchor" href="#the-enumeration" aria-label="Permalink to &quot;The enumeration&quot;">​</a></h2><h3 id="a-—-resource-organization-plan" tabindex="-1">A — Resource organization plan <a class="header-anchor" href="#a-—-resource-organization-plan" aria-label="Permalink to &quot;A — Resource organization plan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-A1</td><td>The landing zone references the subscriptions to use, resource-group usage guidance, and tagging/naming standards for AVS deployments</td><td>⚠️ Partial — <code>Management/AllSubscriptions</code> (subscription inventory), <code>$.tags[*]</code> (tag presence), no naming-convention signal</td></tr></tbody></table><h3 id="b-—-microsoft-entra-id-and-active-directory" tabindex="-1">B — Microsoft Entra ID and Active Directory <a class="header-anchor" href="#b-—-microsoft-entra-id-and-active-directory" aria-label="Permalink to &quot;B — Microsoft Entra ID and Active Directory&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-B1</td><td>Active Directory Sites and Services directs Azure/AVS AD DS traffic to the correct domain controllers</td><td>❌ Organisational/on-premises AD topology — not an ARM resource</td></tr><tr><td>AVS-B2</td><td>An AD DS domain controller is deployed in the identity subscription as part of the IAM landing zone</td><td>❌ Not reliably distinguishable from general VM inventory — no domain-controller-role signal collected</td></tr></tbody></table><h3 id="c-—-network-topology-and-connectivity" tabindex="-1">C — Network topology and connectivity <a class="header-anchor" href="#c-—-network-topology-and-connectivity" aria-label="Permalink to &quot;C — Network topology and connectivity&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-C1</td><td>Traffic-inspection requirements are established for the AVS deployment</td><td>⚠️ Partial — <code>Networking/AzureFirewall</code>, <code>Security/WafPolicies</code> existence</td></tr><tr><td>AVS-C2</td><td>Network traffic flows are documented/understood before migration</td><td>❌ No flow-log or traffic-pattern data collected</td></tr><tr><td>AVS-C3</td><td>Internet egress and ingress paths are defined</td><td>⚠️ Partial — <code>Networking/PublicIP</code>, <code>Networking/NATGateway</code> existence</td></tr><tr><td>AVS-C4</td><td>NVA use is considered where required</td><td>❌ Not distinguishable from general VM/appliance inventory</td></tr><tr><td>AVS-C5</td><td>Connectivity exists to a standard hub VNet or an Azure Virtual WAN hub</td><td>✅ <code>Compute/VMWare</code> &quot;Express Route Circuit&quot; field · <code>Networking/VirtualWAN</code>, <code>Networking/ExpressRoute</code>, <code>Networking/VirtualNetworkGateways</code></td></tr><tr><td>AVS-C6</td><td>Private connectivity is used rather than public exposure</td><td>✅ <code>Networking/PrivateEndpoint</code></td></tr></tbody></table><h3 id="d-—-management-and-monitoring" tabindex="-1">D — Management and monitoring <a class="header-anchor" href="#d-—-management-and-monitoring" aria-label="Permalink to &quot;D — Management and monitoring&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-D1</td><td>Alerts and dashboards exist for the operations-relevant metrics</td><td>⚠️ Partial — <code>Monitor/ActionGroups</code>, <code>Monitor/MetricAlertRules</code>, <code>Monitor/MonitorWorkbooks</code> existence only, not metric relevance</td></tr><tr><td>AVS-D2</td><td>VMware ecosystem tooling (vRealize Operations, Log Insight, Network Insight) is licensed for AVS platform visibility</td><td>❌ Third-party VMware tooling, not an Azure ARM resource</td></tr><tr><td>AVS-D3</td><td>Guest monitoring is configured for AVS VMs per the hybrid Windows/Linux guidance</td><td>⚠️ Partial — <code>Hybrid/ArcExtensions</code> (Azure Monitor Agent extension presence), same limitation as <code>SMART-E1</code></td></tr></tbody></table><h3 id="e-—-business-continuity-and-disaster-recovery" tabindex="-1">E — Business continuity and disaster recovery <a class="header-anchor" href="#e-—-business-continuity-and-disaster-recovery" aria-label="Permalink to &quot;E — Business continuity and disaster recovery&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-E1</td><td>A validated backup solution (MABS or a partner product) protects the AVS VMware VMs</td><td>❌ VMware-native/partner backup agents are not an ARM resource Scout collects — <code>Management/Backup</code> and <code>Management/RecoveryVault</code> cover Azure-native backup only</td></tr><tr><td>AVS-E2</td><td>VMware Site Recovery Manager is configured between primary and secondary sites</td><td>❌ VMware SRM is not ARM-visible; distinct from Azure Site Recovery</td></tr></tbody></table><h3 id="f-—-governance-and-compliance" tabindex="-1">F — Governance and compliance <a class="header-anchor" href="#f-—-governance-and-compliance" aria-label="Permalink to &quot;F — Governance and compliance&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-F1</td><td>Environment governance controls are in place</td><td>✅ <code>Management/PolicyAssignments</code>, <code>Management/PolicyComplianceStates</code></td></tr><tr><td>AVS-F2</td><td>Guest application and VM governance controls are in place</td><td>❌ Guest-OS-level, not observed</td></tr><tr><td>AVS-F3</td><td>Environment and guest compliance are both tracked</td><td>⚠️ Partial — environment half only, via <code>Management/PolicyComplianceStates</code></td></tr></tbody></table><h3 id="g-—-security" tabindex="-1">G — Security <a class="header-anchor" href="#g-—-security" aria-label="Permalink to &quot;G — Security&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-G1</td><td>Identity security for who can perform AVS functions is planned</td><td>⚠️ Partial — <code>Identity/RoleAssignments</code>, <code>Identity/PIMAssignments</code></td></tr><tr><td>AVS-G2</td><td>Environment and network security are reviewed</td><td>⚠️ Partial — <code>Networking/NetworkSecurityGroup</code>, <code>Security/DefenderPricing</code></td></tr><tr><td>AVS-G3</td><td>Guest application and VM security are reviewed</td><td>❌ Guest-OS-level, not observed</td></tr></tbody></table><h3 id="h-—-platform-automation-and-devops" tabindex="-1">H — Platform automation and DevOps <a class="header-anchor" href="#h-—-platform-automation-and-devops" aria-label="Permalink to &quot;H — Platform automation and DevOps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout can evidence?</th></tr></thead><tbody><tr><td>AVS-H1</td><td>Deployment options (manual vs. automated) for the AVS private cloud are decided</td><td>❌ Deployment method is not recorded against the resource</td></tr><tr><td>AVS-H2</td><td>Automated scale considerations and implementation details are documented</td><td>⚠️ Partial — <code>Compute/VMWare</code> &quot;Cluster Size&quot; field is a static snapshot, not a scaling-activity signal</td></tr><tr><td>AVS-H3</td><td>VMware-level automation within the private cloud (NSX-T, vCenter) is considered</td><td>❌ Not ARM-visible</td></tr><tr><td>AVS-H4</td><td>Automation approaches extend from the enterprise landing zone</td><td>⚠️ Partial — <code>$.management.deployments[?(@.properties.templateHash)]</code> (generic IaC-deployment signal, not AVS-specific)</td></tr><tr><td>AVS-H5</td><td>Automation technologies (Azure CLI, ARM templates, Bicep, PowerShell) are chosen for deployment/management</td><td>⚠️ Partial — same IaC-deployment signal as AVS-H4</td></tr></tbody></table><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p><strong>8 of 25 items are fully answerable, 12 are partial, 5 are organisational or VMware-native and out of reach entirely.</strong> The strongest signal Scout already has for this assessment is network connectivity (<code>AVS-C5</code>, <code>AVS-C6</code>) — the <code>Compute/VMWare</code> collector already carries an &quot;Express Route Circuit&quot; field that answers a genuine landing-zone-readiness question directly. The weakest area is BC/DR (<code>AVS-E1</code>, <code>AVS-E2</code>): VMware-native backup and Site Recovery Manager sit entirely outside ARM&#39;s visibility, and no Scout collector will ever close that gap short of reading vCenter/NSX-T APIs directly, which is out of scope for an ARM-based tool. A future <code>caf.avs-landingzone.yaml</code> should mark those <code>manual: true</code> rather than silently omitting them.</p>',33)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
